const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET,POST,PUT,DELETE,OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type,Authorization"
};

const json = (data, status = 200) =>
  new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8", ...CORS }
  });

const html = (body, status = 200) =>
  new Response(body, {
    status,
    headers: { "Content-Type": "text/html; charset=utf-8", ...CORS }
  });

function esc(v = "") {
  return String(v).replace(/[&<>"']/g, c => ({
    "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"
  }[c]));
}

function money(v) {
  if (v === null || v === undefined || v === "") return "";
  const n = Number(v);
  if (!Number.isFinite(n)) return String(v);
  if (n < 1) return new Intl.NumberFormat("vi-VN", { maximumFractionDigits: 2 }).format(n * 1000) + " triệu";
  return new Intl.NumberFormat("vi-VN", { maximumFractionDigits: 2 }).format(n) + " tỷ";
}

function adminOk(req, env) {
  const h = req.headers.get("Authorization") || "";
  return env.ADMIN_KEY && h === `Bearer ${env.ADMIN_KEY}`;
}

async function listProperties(request, env) {
  const url = new URL(request.url);
  const type = url.searchParams.get("type") || "";
  const area = url.searchParams.get("area") || "";
  const price = url.searchParams.get("price") || "";
  const q = url.searchParams.get("q") || "";
  const status = url.searchParams.get("status");

  let sql = `SELECT * FROM properties WHERE 1=1`;
  const params = [];

  if (!status) { sql += ` AND status IN ('active','reserved','sold')`; } else if (status !== "all") { sql += ` AND status = ?`; params.push(status); }
  if (type) { sql += ` AND type = ?`; params.push(type); }
  if (area) { sql += ` AND area = ?`; params.push(area); }
  if (q) {
    sql += ` AND (title LIKE ? OR code LIKE ? OR description LIKE ?)`;
    const x = `%${q}%`; params.push(x, x, x);
  }
  if (price) {
    const cumulativeBands = {
      "under-1b": ["under-1b"],
      "1b-1_5b": ["under-1b","1b-1_5b"],
      "1_5b-2b": ["under-1b","1b-1_5b","1_5b-2b"],
      "2b-2_5b": ["under-1b","1b-1_5b","1_5b-2b","2b-2_5b"],
      "2_5b-3b": ["under-1b","1b-1_5b","1_5b-2b","2b-2_5b","2_5b-3b"]
    }[price];
    const upper = {
      "under-1b": 1,
      "1b-1_5b": 1.5,
      "1_5b-2b": 2,
      "2b-2_5b": 2.5,
      "2_5b-3b": 3
    }[price];
    if (price === "over-3b") {
      sql += ` AND (price_band = ? OR (price_band = '' AND price_billion >= 3))`;
      params.push("over-3b");
    } else if (cumulativeBands && upper !== undefined) {
      const marks = cumulativeBands.map(() => "?").join(",");
      sql += ` AND (price_band IN (${marks}) OR (price_band = '' AND price_billion > 0 AND price_billion <= ?))`;
      params.push(...cumulativeBands, upper);
    }
  }

  sql += ` ORDER BY created_at DESC`;

  const result = await env.DB.prepare(sql).bind(...params).all();
  return json(result.results || []);
}

async function propertyById(id, env) {
  return env.DB.prepare(`SELECT * FROM properties WHERE id = ?`).bind(id).first();
}


