function optimizeMediaUrl(u, width, quality=74){
  const s=String(u||"");
  if(!s.startsWith("/media/")) return s;
  const sep=s.includes("?")?"&":"?";
  return s+sep+"w="+encodeURIComponent(width)+"&q="+encodeURIComponent(quality);
}
function optimizeExternalImageUrl(u, width, quality=68){
  const s=String(u||"");
  if(!/^https:\/\/images\.unsplash\.com\//.test(s)) return s;
  const base=s.split("?")[0];
  return base+"?auto=format&fit=crop&fm=webp&w="+encodeURIComponent(width)+"&q="+encodeURIComponent(quality);
}
function optimizeHomeImageUrl(u, width, quality=68){
  const s=String(u||"");
  return s.startsWith("/media/") ? optimizeMediaUrl(s,width,quality) : optimizeExternalImageUrl(s,width,quality);
}

async function getHomeImage(env, slot, fallback) {
  try {
    if (env.IMAGES) {
      const obj = await env.IMAGES.head(`homepage/${slot}`);
      if (obj) return `/media/homepage/${slot}?v=${encodeURIComponent(obj.uploaded?.toISOString?.() || Date.now())}`;
    }
  } catch (_) {}
  return fallback;
}

