async function searchPage(request, env) {
  const url=new URL(request.url), params=new URLSearchParams(url.search);
  const type=params.get("type")||"", area=params.get("area")||"", price=params.get("price")||"", q=params.get("q")||"", size=params.get("size")||"";
  let sql=`SELECT * FROM properties WHERE status IN ('active','reserved','sold')`, a=[];
  if(type && type!=="Biệt thự") {sql+=` AND lower(trim(type))=lower(trim(?))`;a.push(type)}
  if(area){
    if(area==="Phường Tân Triều") sql+=` AND (lower(trim(area)) LIKE '%phường tân triều%' OR lower(trim(area)) LIKE '%p. tân triều%' OR lower(trim(area)) LIKE '%tân triều%' OR lower(trim(area)) LIKE '%tan trieu%')`;
    else if(area==="Trung tâm Biên Hòa") sql+=` AND (lower(trim(area)) LIKE '%trung tâm biên hòa%' OR lower(trim(area)) LIKE '%biên hòa%' OR lower(trim(area)) LIKE '%bien hoa%' OR lower(trim(area)) LIKE '%trung tam bien hoa%')`;
    else {sql+=` AND lower(trim(area))=lower(trim(?))`;a.push(area)}
  }
  if(q){sql+=` AND (title LIKE ? OR code LIKE ? OR description LIKE ?)`;const x=`%${q}%`;a.push(x,x,x)}
  // Giá được lọc ở JavaScript để hỗ trợ cả price_billion cũ, price_text tự do và price_band.
  if(size==="under-50")sql+=` AND (size LIKE '%m2%' OR size LIKE '%m²%') AND CAST(substr(replace(replace(size,'m²',''),'m2',''),1, instr(replace(replace(size,'m²',''),'m2',''),' ')-1) AS REAL)<50`;
  sql+=` ORDER BY created_at DESC`;
  let rows=(await env.DB.prepare(sql).bind(...a).all()).results||[];
  if(price){
    const upper={"under-1b":1,"1b-1_5b":1.5,"1_5b-2b":2,"2b-2_5b":2.5,"2_5b-3b":3}[price];
    const bandMax={"under-1b":1,"1b-1_5b":1.5,"1_5b-2b":2,"2b-2_5b":2.5,"2_5b-3b":3};
    const parseFlexible=(v)=>{
      let s=String(v??"").toLowerCase().trim().replace(/,/g,".");
      if(!s)return NaN;
      const ty=s.match(/(\d+(?:\.\d+)?)\s*tỷ/);
      let total=ty?Number(ty[1]):0;
      const tr=s.match(/(\d+(?:\.\d+)?)\s*(?:triệu|tr)/);
      if(ty||tr){ if(tr) total+=Number(tr[1])/1000; return total; }
      const n=s.replace(/[^0-9.]/g,"");
      return n?Number(n):NaN;
    };
    rows=rows.filter(r=>{
      let v=Number(r.price_billion);
      if(!(v>0)) v=parseFlexible(r.price_text);
      if(!(v>0) && r.price_band && bandMax[r.price_band]!=null) v=bandMax[r.price_band];
      if(price==="over-3b") return v>=3;
      return Number.isFinite(v) && v<=upper;
    });
  }
  const cards=rows.map(card).join("");
  const label=[type,area,price,q].filter(Boolean).join(" • ");
  const active = type === "Nhà phố" && area === "Phường Tân Triều" ? "tantrieu" : type === "Nhà phố" && area === "Trung tâm Biên Hòa" ? "bienhoa" : type === "Đất nền" ? "datnen" : type === "Căn hộ" ? "canho" : "";
  return html(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tìm BĐS | Nhà Đẹp Biên Hòa</title><link rel="stylesheet" href="/styles.css"><style>${SITE_HEADER_CSS}${SEARCH_CARD_FIX_CSS}</style></head><body>${siteHeader(active)}<section class="cream search-results-section"><div class="wrap"><div class="section-head"><div><div class="kicker">KẾT QUẢ TÌM KIẾM</div><h2>${rows.length} sản phẩm</h2><p class="muted">${esc(label||"Tất cả sản phẩm")}</p></div><a class="btn outline" href="/">Về trang chủ</a></div><div class="cards">${cards||"<p>Không có sản phẩm phù hợp. Hãy thử bỏ bớt bộ lọc.</p>"}</div></div></section>${LISTING_MOTION_SCRIPT}</body></html>`);
}

async function detailPage(code, env) {
  const p=await env.DB.prepare(`SELECT * FROM properties WHERE code=?`).bind(code).first();
  if(!p) return html("<h1 style='font-family:Arial;padding:40px'>Không tìm thấy sản phẩm.</h1>",404);
  const imageSet=parsePropertyImages(p.images||"");
  const fallback="https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=80";
  const imgs=imageSet.gallery.length?imageSet.gallery:[fallback];
  const main=imgs[0], side=imgs.slice(1);
  const galleryJson=JSON.stringify(imgs).replace(/</g,"\u003c");
  return html(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p.title)} | Nhà Đẹp Biên Hòa</title><link rel="stylesheet" href="/styles.css"><style>${SITE_HEADER_CSS}</style></head><body>
  ${siteHeader("")}

  <section><div class="wrap"><div class="detail-grid"><div class="gallery"><img id="mainGalleryImage" class="gallery-main" src="${esc(main)}" alt="${esc(p.title)}" data-index="0" decoding="async" fetchpriority="high"><div class="side">${side.map((x,i)=>`<img src="${esc(x)}" alt="Ảnh ${i+2}" data-index="${i+1}" loading="lazy" decoding="async">`).join("")}</div></div><div class="info"><div class="kicker">${esc(p.type)} • ${esc(p.area)}</div><h1>${esc(p.title)}</h1><h2 style="color:var(--red)">${esc(p.price_text || money(p.price_billion))}</h2><div class="facts"><div class="fact"><b>Diện tích</b>${esc(p.size||"-")}</div><div class="fact"><b>Pháp lý</b>${esc(p.legal||"-")}</div><div class="fact"><b>Đường trước nhà</b>${esc(p.road||"-")}</div><div class="fact"><b>Trạng thái</b><span class="detail-status status-${esc(p.status)}">${esc(statusLabel(p.status))}</span></div></div><div class="fact" style="margin-bottom:10px"><b>Điểm nổi bật</b>${esc(p.highlight||"Đang cập nhật")}</div><div class="fact" style="margin-bottom:16px"><b>Công năng</b>${esc(extractFunction(p))}</div><div class="description">${esc(p.description||"")}</div><div style="display:flex;gap:10px;flex-wrap:wrap"><a class="btn red" href="tel:+84929118789">☎ Gọi 0929 118 789</a><a class="btn outline" href="https://zalo.me/0929118789" target="_blank" rel="noopener">Nhắn Zalo</a></div></div></div></div></section><div id="lightbox" class="lightbox" aria-hidden="true"><button class="lightbox-close" type="button" aria-label="Đóng">×</button><button class="lightbox-prev" type="button" aria-label="Ảnh trước">‹</button><img id="lightboxImage" src="" alt=""><button class="lightbox-next" type="button" aria-label="Ảnh sau">›</button><div id="lightboxCount" class="lightbox-count"></div></div><script>const GALLERY=${galleryJson};let gi=0;const mainImg=document.getElementById('mainGalleryImage'),lb=document.getElementById('lightbox'),lbImg=document.getElementById('lightboxImage'),lbCount=document.getElementById('lightboxCount');function setGallery(i){gi=(i+GALLERY.length)%GALLERY.length;mainImg.src=GALLERY[gi];mainImg.dataset.index=gi;}function openLb(i){setGallery(i);lbImg.src=GALLERY[gi];lbCount.textContent=(gi+1)+' / '+GALLERY.length;lb.classList.add('open');lb.setAttribute('aria-hidden','false');}function closeLb(){lb.classList.remove('open');lb.setAttribute('aria-hidden','true');}document.querySelectorAll('.gallery img').forEach(im=>im.addEventListener('click',()=>openLb(Number(im.dataset.index||0))));document.querySelector('.lightbox-close').onclick=closeLb;document.querySelector('.lightbox-prev').onclick=()=>openLb(gi-1);document.querySelector('.lightbox-next').onclick=()=>openLb(gi+1);lb.addEventListener('click',e=>{if(e.target===lb)closeLb()});document.addEventListener('keydown',e=>{if(!lb.classList.contains('open'))return;if(e.key==='Escape')closeLb();if(e.key==='ArrowLeft')openLb(gi-1);if(e.key==='ArrowRight')openLb(gi+1);});</script></body></html>`);
}
